function cameraError(e){if(e.name==='NotAllowedError')return 'Camera permission was declined. Allow camera access in your browser, then try again, or use Keyboard.';if(e.name==='NotFoundError')return 'No camera was found. Connect a camera or choose Keyboard.';if(e.name==='NotReadableError')return 'The camera is in use. Close other camera apps, then try again.';return e.message||'Camera could not start. Try Keyboard to test the race.';}
