$('#review-button').onclick=()=>{show('#answer-review',$('#answer-review').hidden);$('#answer-review').replaceChildren(...race.questions.map(q=>{const row=document.createElement('div');row.className='review-row';const title=document.createElement('b');title.textContent=`P${q.player+1} · ${q.prompt}`;const detail=document.createElement('span');detail.textContent=`${q.correct?'✓':'○'} ${q.response}`;row.append(title,detail);return row;}));};
let editingIndex=null,drafts=[];
async function persistCustom(next){const approved=await confirmPack(next);if(!approved)return false;try{if(cloudBank.user)await cloudBank.save(approved);localStorage.setItem('sprint-custom',JSON.stringify(approved));custom=approved;renderCustom();syncQuestionSets($('#question-set-select').value);return true;}catch{toast('Could not save the bank. Check your connection and sign-in, then try again.');return false;}}
function resetEditor(){editingIndex=null;$('#question-form').reset();$('#save-question').textContent='Add question +';$('#editor-title').textContent='Write a question';show('#cancel-edit',false);}
function editQuestion(index){editingIndex=index;const q=custom[index];$('#custom-prompt').value=q.prompt;['a','b','c'].forEach((k,i)=>$('#custom-'+k).value=q.options[i]);$('#custom-correct').value=q.correct;$('#save-question').textContent='Save changes';$('#editor-title').textContent='Edit question '+(index+1);show('#cancel-edit');$('#question-form').scrollIntoView({block:'center',behavior:'smooth'});$('#custom-prompt').focus();}
$('#cancel-edit').onclick=resetEditor;
function renderCustom(){$('#custom-count').textContent=custom.length;$('#custom-list').replaceChildren(...custom.map((q,index)=>{const row=document.createElement('div');row.className='custom-row';const div=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('small'),edit=document.createElement('button'),remove=document.createElement('button');strong.textContent=q.prompt;small.textContent=q.options.map((a,i)=>(i===q.correct?'✓ ':'')+['A','B','C'][i]+': '+a).join(' · ');div.append(strong,small);edit.textContent='Edit';edit.ariaLabel='Edit question '+(index+1);edit.onclick=()=>{openStudio('manual');editQuestion(index);};remove.textContent='×';remove.ariaLabel='Remove question '+(index+1);remove.onclick=async()=>{if(await persistCustom(custom.filter((_,i)=>i!==index)))resetEditor();};row.append(div,edit,remove);return row;}));if(!custom.length)$('#custom-list').textContent='Your questions will appear here.';}
$('#question-form').onsubmit=async e=>{e.preventDefault();const q={prompt:$('#custom-prompt').value.trim(),options:[$('#custom-a').value.trim(),$('#custom-b').value.trim(),$('#custom-c').value.trim()],correct:Number($('#custom-correct').value)};if(!validQuestion(q)){toast('Enter a question, three different answers and one correct option.');return;}const next=[...custom];if(editingIndex===null){if(next.length>=300){toast('A pack can contain up to 300 questions.');return;}next.push(q);}else next[editingIndex]=q;if(await persistCustom(next)){resetEditor();toast('Question saved to your editable pack.');}};
$('#export-pack').onclick=()=>{if(!custom.length){toast('Add a question first.');return;}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(custom,null,2)],{type:'application/json'}));a.download='sprint-quiz-questions.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#import-pack').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>500000)throw Error('Pack is too large.');const data=JSON.parse(await f.text());if(!Array.isArray(data)||!data.length||data.length>300||!data.every(validQuestion))throw Error('Use an exported question pack with up to 300 valid questions.');if(await persistCustom(data)){resetEditor();toast('Question pack imported. Every question is editable.');}}catch(err){toast(err.message);}e.target.value='';};
$('#copy-starter').onclick=async()=>{const year=$('#year-select').value==='custom'?'3':$('#year-select').value;if(custom.length+PACKS[year].length>300){toast('This would exceed 300 questions.');return;}if(await persistCustom([...custom,...PACKS[year].map(q=>({...q,options:[...q.options]}))]))toast('Starter questions copied. Use Edit to change any question.');};
$('#use-custom').onclick=()=>{if(!custom.length){toast('Add or import a question first.');return;}$('#year-select').value='custom';syncQuestionSets();show('#teacher-screen',false);toast('Your edited question pack is selected for the next race.');};
function refreshAIPrompt(){$('#ai-prompt').value=buildPrompt($('#ai-year').value,$('#ai-count').value,$('#ai-topic').value);}
['ai-year','ai-count','ai-topic'].forEach(id=>$('#'+id).oninput=refreshAIPrompt);refreshAIPrompt();
$('#ai-copy').onclick=async()=>{refreshAIPrompt();try{await navigator.clipboard.writeText($('#ai-prompt').value);$('#ai-status').textContent='Prompt copied. Paste it into any AI chatbot, then bring its JSON response back here.';}catch{$('#ai-prompt').focus();$('#ai-prompt').select();$('#ai-status').textContent='Select and copy the prompt above, then paste it into any AI chatbot.';}};
function renderDrafts(){const host=$('#ai-drafts');host.replaceChildren(...drafts.map((q,index)=>{const card=document.createElement('fieldset');card.className='draft-card';const title=document.createElement('legend');title.textContent='Draft '+(index+1);card.append(title);function field(label,value,onchange,max){const wrap=document.createElement('label');wrap.textContent=label;const el=document.createElement('input');el.value=value;el.maxLength=max;el.oninput=()=>onchange(el.value);wrap.append(el);return wrap;}card.append(field('Question',q.prompt,v=>q.prompt=v,150));const answers=document.createElement('div');answers.className='custom-options';q.options.forEach((v,i)=>answers.append(field(['A','B','C'][i],v,v=>q.options[i]=v,55)));card.append(answers);const label=document.createElement('label');label.textContent='Correct answer';const select=document.createElement('select');['A','B','C'].forEach((v,i)=>{const o=document.createElement('option');o.value=i;o.textContent=v;select.append(o);});select.value=q.correct;select.onchange=()=>q.correct=Number(select.value);label.append(select);const remove=document.createElement('button');remove.className='text-button';remove.textContent='Discard draft';remove.onclick=()=>{drafts.splice(index,1);renderDrafts();};card.append(label,remove);return card;}));show('#ai-accept',drafts.length>0);}
$('#ai-import').onclick=()=>{try{const parsed=parseDrafts($('#ai-response').value);drafts=parsed;renderDrafts();$('#ai-status').textContent=`${drafts.length} drafts ready. Check the wording and marked correct answer before adding them.`;}catch(e){$('#ai-status').textContent=e.message;}};
$('#ai-accept').onclick=async()=>{if(!drafts.length||!drafts.every(validQuestion)){$('#ai-status').textContent='Check each draft: a question, three different answers, and one correct answer are required.';return;}if(custom.length+drafts.length>300){$('#ai-status').textContent='Your pack can contain up to 300 questions.';return;}if(await persistCustom([...custom,...drafts.map(q=>({...q,options:[...q.options]}))])){drafts=[];renderDrafts();$('#ai-response').value='';$('#ai-status').textContent='Reviewed drafts added. You can continue editing them in your pack below.';}};
async function createPair(){clearInterval(pairTimer);phoneConnection?.close();cameraReady=false;$('#camera-race-button').disabled=true;$('#pair-qr').textContent='Creating a secure camera link…';$('#pair-pin-code').textContent='— — — — — —';$('#camera-status').textContent='Connecting the two devices…';$('#calibrate-button').textContent='Create new link';try{const pc=phoneConnection=new RTCPeerConnection(rtcConfig),channel=pc.createDataChannel('motion',{ordered:false,maxRetransmits:0});phoneChannel=channel;channel.onmessage=e=>{try{const state=JSON.parse(e.data);phoneLostAt=performance.now();lastCameraState=state;handleMotion(state);if(state.calibrated){cameraReady=true;$('#camera-race-button').disabled=false;$('#camera-status').textContent='Phone connected and calibrated. Start the race when everyone is ready.';}else $('#camera-status').textContent=`Phone connected · ${state.detected||0}/${settings.players} players visible. Calibrate on the phone.`;}catch{}};channel.onopen=()=>{$('#camera-status').textContent='Phone connected. Enable its camera and calibrate the players.';};channel.onclose=()=>{cameraReady=false;$('#camera-race-button').disabled=true;if(race)pause('Reconnect your phone.','The camera connection stopped. Return to setup and pair the phone again.');};const offer=await gather(pc),id=crypto.randomUUID();if(phoneConnection!==pc||$('#camera-screen').hidden)return;const response=await pairRequest('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,offer,players:settings.players})});if(!response.ok)throw Error('Could not create the pairing link. Try again.');const pairing=await response.json();if(phoneConnection!==pc||$('#camera-screen').hidden){await pairRequest('/api/pair',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});return;}$('#pair-pin-code').textContent=pairing.pin.slice(0,3)+' '+pairing.pin.slice(3);$('#pair-pin-expiry').textContent='Valid for 5 minutes · one camera device';const link=new URL('./index.html',import.meta.url);link.hash='camera='+id;$('#pair-link').href=link;const qr=window.qrcode?.(0,'M');if(qr){qr.addData(link.href);qr.make();$('#pair-qr').innerHTML=qr.createSvgTag({scalable:true,margin:2});}else $('#pair-qr').textContent='Open the camera controller link below on your phone.';$('#camera-status').textContent=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'Local preview: use the hosted HTTPS link for a phone camera. Laptop camera works here.':'Scan the QR code. On your phone, open the link and enable its camera.';let polls=0;pairTimer=setInterval(async()=>{try{if(++polls>200){clearInterval(pairTimer);$('#camera-status').textContent='Pairing link timed out. Create a new one.';return;}const res=await pairRequest('/api/pair?id='+id,{cache:'no-store'});if(!res.ok)return;const data=await res.json();if(data.answer&&!pc.remoteDescription){await pc.setRemoteDescription(data.answer);clearInterval(pairTimer);await pairRequest('/api/pair',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});}}catch{}},1500);}catch(e){$('#pair-qr').textContent='';$('#camera-status').textContent=e.message;}}
async function startPhone(id){qrScanner.stop();music.suspend('phone');show('#home',false);show('#splash',false);show('#nav',false);show('#selection-screen',false);show('#phone-controller');show('#load-status',false);try{const res=await pairRequest('/api/pair?id='+id,{cache:'no-store'});if(!res.ok)throw Error('This pairing link expired. Create a new QR code on the game screen.');const data=await res.json(),pc=new RTCPeerConnection(rtcConfig);phoneConnection=pc;let dataChannel=null;pc.ondatachannel=e=>{dataChannel=e.channel;dataChannel.onopen=()=>{$('#phone-status').textContent='Connected! Enable the camera to begin.';$('#phone-enable').disabled=false;requestWakeLock();};dataChannel.onclose=()=>{$('#phone-status').textContent='Game disconnected. Create a new link on the game screen.';camera?.stop();};};await pc.setRemoteDescription(data.offer);await pc.setLocalDescription(await pc.createAnswer());if(pc.iceGatheringState!=='complete')await new Promise(resolve=>{const timer=setTimeout(resolve,4500);pc.onicegatheringstatechange=()=>{if(pc.iceGatheringState==='complete'){clearTimeout(timer);resolve();}};});const answered=await pairRequest('/api/pair',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,answer:pc.localDescription})});if(!answered.ok)throw Error((await answered.json()).error);$('#phone-status').textContent='Connecting to the game screen…';setTimeout(()=>{if(pc.connectionState!=='connected')$('#phone-status').textContent='Still connecting. Put both devices on the same Wi-Fi and create a new link if needed.';},15000);
$('#phone-enable').onclick=async()=>{$('#phone-enable').disabled=true;try{camera?.stop();camera=new CameraController({video:$('#phone-video'),canvas:$('#phone-overlay'),zones:$('#phone-zones'),count:data.players,onStatus:s=>$('#phone-status').textContent=s,onState:state=>{if(dataChannel?.readyState==='open')dataChannel.send(JSON.stringify(state));}});await camera.start();$('#phone-calibrate').disabled=false;$('#phone-enable').textContent='Camera enabled';}catch(e){$('#phone-status').textContent=cameraError(e);$('#phone-enable').disabled=false;}};$('#phone-calibrate').onclick=()=>{if(camera.calibrate())$('#phone-status').textContent='Ready! Start the race on the game screen. Keep this phone still.';};}catch(e){$('#phone-status').textContent=e.message;}}

function mainMenu(){resetMenuPanel();stopSelectionCamera();music.setTrack('menu');show('#pack-picker',false);show('#menu-artwork');show('#splash',false);$('#menu-back').ariaLabel='Return to splash screen';show('#home');show('#nav');show('#selection-screen',false);$('#page-title').textContent='Main Menu';}
$('#splash-start').onclick=mainMenu;
$('#menu-back').onclick=()=>{if(!$('#selection-screen').hidden){mainMenu();return;}if(embeddedPanel||!$('#pack-picker').hidden){mainMenu();return;}show('#home',false);show('#nav',false);show('#splash');music.setTrack('menu');};
function renderPlayerSelection(){const count=Number($('#players-select').value);selectionPlayer=Math.min(selectionPlayer,count-1);$('#selection-title').textContent=mode==='solo'?'Your character':'Select the number of players.';show('#solo-character',mode==='solo');show('#player-tiles',mode==='class');$('#character-preview').src=stadium.athletes.portraits[selectedCharacters[selectionPlayer]];$('#player-tiles').replaceChildren(...[2,3,4].map(number=>{const button=document.createElement('button');button.className='player-count-tile';button.ariaLabel=number+' players';button.ariaPressed=String(count===number);const strong=document.createElement('strong');strong.className='player-count-number';strong.textContent=number;button.append(strong);button.onclick=()=>{if(count!==number)stopSelectionCamera();$('#players-select').value=number;renderPlayerSelection();};return button;}));$('#selection-player-tabs').replaceChildren(...Array.from({length:count},(_,i)=>{const b=document.createElement('button');b.textContent='P'+(i+1);b.classList.toggle('active',i===selectionPlayer);b.onclick=()=>{selectionPlayer=i;renderPlayerSelection();};return b;}));$('#character-options').replaceChildren(...stadium.athletes.portraits.map((src,i)=>{const button=document.createElement('button');button.className='character-choice';button.ariaLabel=`Choose character ${i+1} for player ${selectionPlayer+1}`;button.ariaPressed=String(selectedCharacters[selectionPlayer]===i);const art=document.createElement('img');art.src=src;art.alt='';button.append(art);button.onclick=()=>{selectedCharacters[selectionPlayer]=i;renderPlayerSelection();};return button;}));}
function playerSelection(kind){resetMenuPanel();setMode(kind);show('#home',false);show('#selection-screen');$('#page-title').textContent='Players';$('#menu-back').ariaLabel='Back to main menu';selectionPlayer=0;renderPlayerSelection();}
$('#single-menu').onclick=()=>choosePack('solo');$('#multi-menu').onclick=()=>choosePack('class');
$('#selection-next').onclick=()=>{if(input==='camera'&&camera?.selection&&!camera.calibrated){toast('Stand in your numbered areas and lock the players first.');return;}openSettings();};$('#settings-menu').onclick=()=>openMenuPanel('preferences-screen');$('#pair-menu').onclick=()=>openMenuPanel('pair-menu-screen');$('#help-menu').onclick=()=>openMenuPanel('help-screen');
$('#host-pair').onclick=()=>{setInput('phone');openSettings();};
function getHistory(){try{const value=JSON.parse(localStorage.getItem('chase-races')||'[]');return Array.isArray(value)?value.filter(v=>v&&typeof v.date==='string'&&typeof v.mode==='string'&&Array.isArray(v.players)).slice(0,20):[];}catch{return [];}}
function saveRaceHistory(){const entry={date:new Date().toISOString(),mode:settings.finish,time:race.time,players:[...race.players,...race.ai].sort((a,b)=>a.rank-b.rank).map(p=>({id:p.id,name:playerLabel(p),rank:p.rank,ai:!!p.ai,distance:Math.floor(p.distance),correct:p.correct??null}))};try{localStorage.setItem('chase-races',JSON.stringify([entry,...getHistory()].slice(0,20)));}catch{toast('Race finished. Browser storage is full, so this result could not be saved.');}}
$('#leaderboard-menu').onclick=()=>{const entries=getHistory(),host=$('#history-list');host.replaceChildren(...entries.map(e=>{const card=document.createElement('section');card.className='history-race';const h=document.createElement('h3');h.textContent=new Date(e.date).toLocaleString()+` · ${e.mode} · ${clock(e.time)}`;const list=document.createElement('ol');e.players.forEach((p,i)=>{const li=document.createElement('li');li.textContent=`${p.id!==undefined?playerLabel(p):p.ai?'AI '+(i+1):'P'+(i+1)} — ${p.distance}m${p.correct===null?'':` · ${p.correct} correct`}`;list.append(li);});card.append(h,list);return card;}));if(!entries.length)host.textContent='Your first finish is waiting. Complete a race to set a result.';openMenuPanel('history-screen');};
function setLoading(value,message){$('#loading-fill').style.width=value+'%';$('.loading-progress').setAttribute('aria-valuenow',value);$('#loading-text').textContent=message;}
$('#loading-retry').onclick=()=>location.reload();
const panelHomes=new Map();let embeddedPanel=null,packYear=null;
function resetMenuPanel(){if(embeddedPanel){const panel=$('#'+embeddedPanel);if(panel.id==='join-screen')stopQR();panel.hidden=true;panel.classList.remove('embedded-panel');panelHomes.get(embeddedPanel)?.append(panel);embeddedPanel=null;}show('#menu-panel-host',false);show('#pack-picker',false);show('#menu-artwork');}
function openMenuPanel(id){resetMenuPanel();const panel=$('#'+id);if(!panelHomes.has(id))panelHomes.set(id,panel.parentElement);$('#menu-panel-host').append(panel);panel.classList.add('embedded-panel');embeddedPanel=id;show('#menu-artwork',false);show('#menu-panel-host');show('#'+id);$('#menu-panel-host').scrollTop=0;}
document.addEventListener('pointerdown',e=>{if(embeddedPanel&&!$('#menu-panel-host').contains(e.target)&&!e.target.closest('#nav,.menu-primary,.menu-secondary')&&!$$('.modal-backdrop').some(p=>!p.hidden&&!p.classList.contains('embedded-panel')))resetMenuPanel();});
function openSettings(){if(!$('#home').hidden)openMenuPanel('settings-screen');else{resetMenuPanel();show('#settings-screen');}}
function openStudio(kind){renderCustom();for(const name of ['ai','manual','bank'])show('#studio-'+name,name===kind);$('#studio-title').textContent={ai:'AI assist',manual:'Manual Edit',bank:'Question Bank'}[kind];$('#studio-description').textContent={ai:'Use any AI chatbot, then review and edit the draft questions.',manual:'Write a question, add three choices and mark the correct answer.',bank:'Manage the saved questions used in your custom race sets.'}[kind];show('#teacher-screen');$('.teacher-dialog').scrollTop=0;}
$$('[data-studio]').forEach(b=>b.onclick=()=>{if(b.dataset.studio==='manual')resetEditor();openStudio(b.dataset.studio);});
function syncQuestionSets(selected='all'){const bank=$('#year-select').value==='custom'?custom:PACKS[$('#year-select').value];$('#question-set-select').replaceChildren(...questionSets(bank).map(set=>{const option=document.createElement('option');option.value=set.id;option.textContent=set.title+' · '+set.questions.length;return option;}));$('#question-set-select').value=selected;if(!$('#question-set-select').value)$('#question-set-select').value='all';}
$('#year-select').onchange=()=>syncQuestionSets();syncQuestionSets();
function choosePack(kind){resetMenuPanel();setMode(kind);packYear=null;$('#pack-mode').textContent=kind==='solo'?'SINGLE PLAYER':'MULTIPLAYER';$('#pack-title').textContent='Choose your question bank.';$('#pack-description').textContent='Choose a bank to see its question sets.';show('#menu-artwork',false);show('#pack-picker');$('#pack-options').replaceChildren(...['1','3','4','custom'].map(year=>{const button=document.createElement('button');button.className='pack-choice';const title=document.createElement('strong'),detail=document.createElement('span');title.textContent=year==='custom'?'My question bank':`Year ${year} · English`;detail.textContent=year==='custom'?`${custom.length} saved questions`:`${PACKS[year].length} questions`;button.append(title,detail);button.onclick=()=>chooseSets(year);return button;}));}
function chooseSets(year){packYear=year;$('#pack-title').textContent=year==='custom'?'My question sets':`Year ${year} · English`;$('#pack-description').textContent='Choose a set for this race.';const bank=year==='custom'?custom:PACKS[year];$('#pack-options').replaceChildren(...questionSets(bank).map(set=>{const button=document.createElement('button');button.className='pack-choice';const title=document.createElement('strong'),detail=document.createElement('span');title.textContent=set.title;detail.textContent=set.detail;button.append(title,detail);button.disabled=!set.questions.length;button.onclick=()=>{$('#year-select').value=year;syncQuestionSets(set.id);playerSelection(mode);};return button;}));if(!bank.length){$('#pack-description').textContent='Your bank is empty. Create or import questions to build your first set.';const b=document.createElement('button');b.className='primary';b.textContent='Open Question Bank';b.onclick=()=>openMenuPanel('bank-menu-screen');$('#pack-options').append(b);}}
$('#pack-cancel').onclick=()=>packYear?choosePack(mode):mainMenu();
function stopSelectionCamera(){if(camera?.selection){camera.stop();camera=null;cameraReady=false;}$('#selection-camera-lock').disabled=true;$('#selection-camera-enable').disabled=false;$('#selection-camera-enable').textContent='Enable camera';$('#selection-camera-status').textContent='Enable the camera to detect players in their numbered areas.';show('#selection-camera-empty');}
$('#selection-camera-enable').onclick=async()=>{stopSelectionCamera();setInput('camera');const count=Number($('#players-select').value);$('#selection-camera-enable').disabled=true;const controller=new CameraController({video:$('#selection-video'),canvas:$('#selection-overlay'),zones:$('#selection-zones'),count,onStatus:message=>$('#selection-camera-status').textContent=message,onState:data=>{if(camera!==controller)return;handleMotion(data);const all=data.detected===count;$('#selection-camera-lock').disabled=!all;$('#selection-camera-status').textContent=data.calibrated?(all?`${count} ${count===1?'player':'players'} locked · ready to race`:'Player tracking lost. Return to your numbered area.'):`${data.detected} / ${count} players detected · stand still to lock`;$('#selection-camera-lock').textContent=data.calibrated?'Lock again':'Lock players';}});controller.selection=true;camera=controller;try{await controller.start();if(camera!==controller)return;show('#selection-camera-empty',false);$('#selection-camera-enable').textContent='Camera active';}catch(e){if(camera===controller){controller.stop();camera=null;$('#selection-camera-enable').disabled=false;$('#selection-camera-status').textContent=cameraError(e);}}};
$('#selection-keyboard').onclick=()=>{setInput('keyboard');$('#selection-camera-status').textContent='Keyboard selected. Continue to race settings when ready.';};
$('#selection-camera-lock').onclick=()=>{if(camera?.calibrate()){cameraReady=true;$('#selection-camera-lock').textContent='Lock again';$('#selection-camera-status').textContent=`${camera.count} ${camera.count===1?'player':'players'} locked · ready to race`;}};
$('#players-select').onchange=()=>{stopSelectionCamera();renderPlayerSelection();};

const cloudBank=new CloudBank();
cloudBank.onchange=state=>{const status=$('#cloud-bank-status');$('#cloud-signin').disabled=!state.ready;show('#cloud-signin',!state.user);show('#cloud-signout',!!state.user);show('#cloud-upload',!!state.user);if(!state.ready){status.textContent='Firebase connection is being set up. Your bank stays on this device.';return;}if(state.error){status.textContent='Cloud bank could not load. '+state.error.message;return;}if(state.user){if(state.questions!==null&&state.questions!==undefined){try{localStorage.setItem('sprint-custom-backup',JSON.stringify(custom));localStorage.setItem('sprint-custom',JSON.stringify(state.questions));custom=state.questions;renderCustom();syncQuestionSets();}catch{toast('Cloud bank loaded, but this browser could not store a local copy.');}}status.textContent='Signed in · question bank saves sync across your devices.';}else status.textContent='Sign in with Google to sync your own question bank. Local questions remain editable.';};
$('#cloud-signin').onclick=async()=>{try{await cloudBank.signIn();}catch(e){toast('Google sign-in could not finish: '+e.message);}};
$('#cloud-signout').onclick=async()=>{try{await cloudBank.signOut();}catch(e){toast(e.message);}};
$('#cloud-upload').onclick=async()=>{if(await persistCustom(custom))toast('Question bank saved to Firebase.');};
cloudBank.start().catch(e=>$('#cloud-bank-status').textContent='Firebase is unavailable: '+e.message);

const saveGate=new SaveConfirmation();let resolveSave=null;
function confirmPack(next){if(resolveSave)return Promise.resolve(false);saveGate.begin(next);renderSaveConfirmation();show('#save-confirm-screen');$('#save-confirm-next').focus();return new Promise(resolve=>resolveSave=resolve);}
function cancelSave(){saveGate.cancel();show('#save-confirm-screen',false);const resolve=resolveSave;resolveSave=null;resolve?.(false);}
function renderSaveConfirmation(){const level=saveGate.level;$('#save-confirm-screen').dataset.level=level;$('#save-confirm-level').textContent=`CONFIRMATION ${level} OF 3`;$('#save-confirm-title').textContent=['Review your changes.','Replace the saved bank?','Final confirmation.'][level-1];$('#save-confirm-copy').textContent=['Check the proposed questions and correct answers below. Nothing has been saved yet.','Continuing will prepare to replace the current saved question bank on this device. Cancel to keep the existing bank.','The next click saves these changes and makes this bank available for future races. Confirm only when you are satisfied with every answer.'][level-1];$('#save-confirm-next').textContent=level===3?'Yes — save this bank now':level===2?'I understand — final check':'Reviewed — continue';const next=saveGate.proposal,host=$('#save-confirm-summary');host.replaceChildren();const count=document.createElement('strong');count.textContent=`${custom.length} saved questions → ${next.length} proposed questions`;host.append(count);const changed=next.filter((q,i)=>JSON.stringify(q)!==JSON.stringify(custom[i]));for(const q of changed.slice(0,15)){const row=document.createElement('p');row.textContent=q.prompt+' · '+q.options.map((a,i)=>(i===q.correct?'✓ ':'')+a).join(' / ');host.append(row);}if(next.length<custom.length){const note=document.createElement('p');note.textContent=`${custom.length-next.length} question(s) will be removed.`;host.append(note);}if(changed.length>15){const note=document.createElement('p');note.textContent=`Plus ${changed.length-15} more changed questions from the draft you reviewed.`;host.append(note);}}
$('#save-confirm-cancel').onclick=cancelSave;
$('#save-confirm-next').onclick=()=>{const committed=saveGate.advance();if(committed){show('#save-confirm-screen',false);const resolve=resolveSave;resolveSave=null;resolve?.(committed);}else renderSaveConfirmation();};
const qrScanner=new QRScanner($('#qr-scan-video'),$('#qr-scan-canvas'),async id=>{show('#join-screen',false);location.hash='camera='+id;await startPhone(id);},message=>$('#qr-scan-status').textContent=message);
function stopQR(){qrScanner.stop();show('#qr-scan-wrap',false);show('#qr-scan-stop',false);$('#qr-scan-start').disabled=false;}
$('#qr-scan-start').onclick=async()=>{if(!window.jsQR){$('#qr-scan-status').textContent='The scanner could not load. Refresh, use your device Camera app, or enter the PIN.';return;}show('#qr-scan-wrap');show('#qr-scan-stop');$('#qr-scan-start').disabled=true;try{await qrScanner.start();}catch{stopQR();}};
$('#qr-scan-stop').onclick=stopQR;
function closePopup(panel){if(panel.classList.contains('embedded-panel')){resetMenuPanel();return;}if(panel.id==='save-confirm-screen'){cancelSave();return;}if(panel.id==='camera-screen'){closeCamera();return;}if(panel.id==='join-screen')stopQR();if(panel.id==='results'){goHome();return;}if(panel.id==='pause-screen'){resume();show('#pause-screen',false);return;}show('#'+panel.id,false);}
window.addEventListener('beforeunload',()=>{qrScanner.stop();camera?.stop();phoneConnection?.close();});
try{const cameraId=new URLSearchParams(location.hash.slice(1)).get('camera');if(cameraId){await loadingSequence(()=>startPhone(cameraId),value=>setLoading(Math.round(value),'Preparing the camera connection…'));show('#loading-screen',false);}else{stadium=new Stadium($('#stadium'));await loadingSequence(()=>stadium.loadCharacters(),value=>setLoading(Math.round(value),value>=100?'Ready to race!':'Loading your stadium…'));setLoading(100,'Ready to race!');show('#loading-screen',false);show('#splash');show('#load-status',false);$('#splash-start').disabled=false;$('#splash-start').textContent='Press to Start →';if(location.hash==='#join'){show('#splash',false);show('#home');show('#nav');show('#join-screen');$('#join-pin').focus();}let last=performance.now();function frame(now){if(now-last<32){requestAnimationFrame(frame);return;}const dt=Math.min(.06,(now-last)/1000);last=now;if(document.hidden||!$('#phone-controller').hidden){requestAnimationFrame(frame);return;}if(race){const prev=race.phase;race.tick(dt);const impacts=impactKeys(race).filter(key=>!playedImpacts.has(key));impacts.forEach(key=>playedImpacts.add(key));if(impacts.length&&!muted){try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();playOof(audio);}catch{}}else if(race.phase==='feedback'&&prev!=='feedback')sound(race.players[0].lastResult.startsWith('Correct'));if(race.finished&&prev!=='results')finishRace();if(input==='phone'&&phoneLostAt&&now-phoneLostAt>2500&&!race.paused&&!race.finished)pause('Waiting for your phone.','The camera signal stopped. Keep the phone browser open, then resume when it reconnects.');if(now-lastUI>70){updateUI();lastUI=now;}}if(race)stadium.update(dt,race);requestAnimationFrame(frame);}requestAnimationFrame(frame);}}catch(e){$('#load-status').textContent='The stadium could not load. Check your connection, then refresh.';$('#loading-text').textContent='The game could not finish loading. Check your connection and try again.';show('#loading-retry');console.error(e);}
